r.append(R(3840,"آئرش پب بھری شملہ مرچیں","کیا آپ سینٹ پیٹرکس ڈے کے لیے گردوں کے لیے موزوں کوئی خاص ترکیب تلاش کر رہے ہیں؟ آئرش پب بھرے آلو شیفرڈز پائی کی بھرائی کو ملاتے ہیں، جو شملہ مرچ کی کشتی میں بیک کی جاتی ہے اور اوپر پھینٹے ہوئے آلو (پوٹاشیم قابو میں رکھنے کے لیے دو بار ابالے گئے) ڈالے جاتے ہیں۔","8","1/2 بھری ہوئی شملہ مرچ",
["4 درمیانی ہری شملہ مرچیں","1 پاؤنڈ گائے کا قیمہ، 10% چکنائی والا","2 کھانے کے چمچ کارن اسٹارچ","2 کھانے کے چمچ ٹھنڈا پانی","2 کپ کم سوڈیم گائے کے گوشت کا شوربہ","2 کھانے کے چمچ کم سوڈیم ورسسٹرشائر ساس","1-1/2 چائے کے چمچ فوری کافی پاؤڈر، خشک","2 کپ منجمد ملی جلی سبزیاں (گاجر، مکئی، ہری پھلیاں، مٹر)","2 کپ سفید آلو","1 کھانے کا چمچ مکھن","3 کھانے کے چمچ آدھا دودھ آدھی کریم (ہاف اینڈ ہاف)"],
["اوون کو 350° F پر پہلے سے گرم کریں۔","آلو چھیل کر چھوٹے ٹکڑوں میں کاٹ لیں۔","شملہ مرچوں کے ڈنٹھل لگے رہنے دیں اور ڈنٹھل سے نیچے تک آدھا کاٹ لیں۔ چمچ سے بیج اور جھلی نکال دیں۔ نان اسٹک کوکنگ اسپرے لگی بیکنگ شیٹ پر رکھیں۔","کارن اسٹارچ کو ٹھنڈے پانی میں ملائیں اور گانٹھیں ختم ہونے تک ہلائیں۔","ساس پین میں گائے کے گوشت کا شوربہ، ورسسٹرشائر ساس اور کافی پاؤڈر ملائیں۔ گھلا ہوا کارن اسٹارچ ڈالیں اور درمیانی آنچ پر گاڑھا ہونے تک ہلائیں۔","کڑاہی میں قیمے کو چورا کریں؛ درمیانی آنچ پر بھورا ہونے تک پکائیں۔ ملی جلی سبزیاں ڈالیں، ہلائیں اور قیمے کے ساتھ گرم ہونے تک گرم کریں۔ گریوی کو قیمے اور سبزیوں کے مکسچر میں ملا دیں۔","ہر شملہ مرچ کے آدھے حصے میں 1/2 کپ گوشت کا مکسچر بھریں۔ اوون میں رکھیں اور بغیر ڈھانپے 40 منٹ بیک کریں۔","جب شملہ مرچیں بیک ہو رہی ہوں تو کم پوٹاشیم والے آلو بنائیں۔ کٹے ہوئے آلو ایک برتن میں رکھیں اور 6 کپ پانی ڈالیں؛ ابال آنے دیں۔ آنچ سے اتاریں اور پانی نکال دیں۔ تازہ پانی ڈالیں اور آلو نرم ہونے تک ابالیں۔","ہینڈ مکسر سے آلوؤں کو مکھن یا مارجرین اور نان ڈیری کریمر یا ہاف اینڈ ہاف کے ساتھ پھینٹیں۔","شملہ مرچوں کو اوون سے نکالیں۔ ہر بھری ہوئی شملہ مرچ کے آدھے حصے کے اوپر 1/4 کپ پھینٹے ہوئے آلو پھیلائیں اور پیش کریں۔"],
["اگر چاہیں تو پیش کرنے سے پہلے Tabasco® ساس یا کم سوڈیم ورسسٹرشائر ساس کا ایک چھینٹا ڈالیں۔","ایک چائے کے چمچ کم سوڈیم ورسسٹرشائر ساس میں 45 mg سوڈیم ہوتا ہے۔","اگر چاہیں تو گائے کے گوشت کی جگہ بھیڑ کا گوشت یا ٹرکی کا قیمہ استعمال کریں۔","اگر چاہیں تو مکھن کی جگہ مارجرین یا ہاف اینڈ ہاف کی جگہ نان ڈیری کریمر استعمال کریں۔"],
["2 گوشت","1/2 نشاستہ","2 سبزیاں، کم پوٹاشیم والی"]))
r.append(R(3846,"گرل کیا ہوا میرینیٹ چکن","کسی بھی سلاد کے ساتھ بہترین مرکزی ڈش گردوں کے لیے موزوں گرل کیا ہوا میرینیٹ چکن ہے۔ اگر آپ پہلے چکن شروع کر دیں تو جب آپ سائیڈ ڈش یا سلاد بنا رہے ہوں گے وہ میرینیٹ ہوتا رہے گا۔ یا چکن کو زپ والے بیگ میں رکھ کر رات بھر میرینیٹ ہونے دیں۔ جو بھی طریقہ آپ کے وقت کے لحاظ سے سب سے موزوں ہو، وہی اپنائیں!","4","1 چکن بریسٹ (2 فلیٹ)",
["4 ہڈی اور کھال کے بغیر چکن بریسٹ","1 لہسن کی کلی","1/4 کپ زیتون کا تیل","1/4 کپ ریڈ وائن سرکہ","1 چائے کا چمچ پیاز پاؤڈر","1-1/2 چائے کے چمچ خشک اطالوی مصالحوں کا مکس","1/2 چائے کا چمچ خشک تھائم","تازہ تھائم کی ٹہنیاں (اختیاری)"],
["چکن بریسٹ کو چوڑائی میں آدھا کاٹ لیں، ہر بریسٹ سے دو پتلے فلیٹ بنائیں۔","لہسن کو باریک کاٹیں اور باقی اجزا کے ساتھ زپ والے بیگ میں ملائیں؛ اچھی طرح ملائیں۔","چکن کے فلیٹ بیگ میں ڈالیں۔ بند کریں اور فرج میں 2 گھنٹے یا اس سے زیادہ میرینیٹ ہونے دیں، کبھی کبھار پلٹتے رہیں۔","چکن کو میرینیڈ سے نکالیں اور درمیانی آنچ پر گرل کریں جب تک چکن پک نہ جائے، ایک بار پلٹیں۔ اگر گوشت کا تھرمامیٹر استعمال کریں تو درجہ حرارت 165º F تک پہنچنا چاہیے۔ اگر چاہیں تو گرل کرتے وقت چکن کے اوپر تازہ تھائم کی ٹہنیاں رکھیں۔"],
["گرل کرنے کے لیے بہت ٹھنڈ ہے؟ چکن پکانے کے لیے اپنا براؤلر استعمال کریں۔","اگر آپ کم پروٹین والی غذا پر ہیں تو مقدار کو 1 فلیٹ یا اپنے کھانے کے منصوبے میں بتائی گئی مقدار تک کم کر سکتے ہیں۔"],
["3-1/2 گوشت"]))
r.append(R(3847,"سول اَن پاپیوٹ (کاغذ میں سول مچھلی)","الاباما سے ڈی ویٹا کی غذائی ماہر کرسٹی کی طرف سے صحت بخش، اعلیٰ ذائقے کے اور گردوں کے لیے موزوں کھانے سے لطف اٹھائیں۔ سول اَن پاپیوٹ (کاغذ میں سول مچھلی) مچھلی اور سبزیوں کا پورا کھانا ایک چھوٹی سی تھیلی میں تیار کرنے کا شاندار طریقہ ہے۔","4","1 فلیٹ اور 3/4 کپ سبزیاں",
["1 پاؤنڈ سول مچھلی کے فلیٹس، کچے","2 چائے کے چمچ کالی مرچ","2 چائے کے چمچ خشک تلسی کے پتے","4 چائے کے چمچ بغیر نمک کا مکھن","40 تازہ ہری پھلیاں","1/2 کپ پیلی شملہ مرچ","1/2 کپ ہری شملہ مرچ","1/2 کپ سرخ پیاز","4 لہسن کی کلیاں","2 تازہ لیموں","ایلومینیم فوائل یا پارچمنٹ پیپر"],
["اوون کو 350° F پر پہلے سے گرم کریں۔","پارچمنٹ پیپر (پاپیوٹ میں) استعمال کر کے تیار کرنے کے لیے پارچمنٹ پیپر کو آدھا موڑیں اور بڑے “آدھے دل” کی شکل میں کاٹ لیں۔ (کیا آپ کو پرائمری اسکول میں ویلنٹائن کارڈ بنانا یاد ہے؟)","کاغذ کھولیں اور ایک فلاؤنڈر فلیٹ کو کھال والی طرف نیچے رکھ کر دل کی شکل والے پارچمنٹ پیپر کی ایک طرف رکھیں، کناروں کے گرد اتنی جگہ چھوڑیں کہ اسے مکمل طور پر بند کیا جا سکے۔ ہر فلیٹ پر 1/2 چائے کا چمچ پسی ہوئی کالی مرچ اور 1/2 چائے کا چمچ تلسی کے پتے چھڑکیں۔ ہر فلیٹ کے اوپر ایک چائے کا چمچ بغیر نمک کا مکھن رکھیں۔ مچھلی کو ایک طرف رکھ دیں۔","ہری پھلیوں کو تراش لیں۔ ہری پھلیوں کو ہلکا ابال لیں؛ ایک طرف رکھ دیں۔","شملہ مرچوں کے بیج نکال دیں۔ مرچوں اور پیاز کو باریک کاٹیں۔ لہسن کی کلیوں کو باریک کاٹ لیں۔","پیلی اور ہری مرچیں، پیاز اور لہسن کو ایک پیالے میں ملائیں۔ لیموں کا رس پیالے میں نچوڑیں۔ اچھی طرح ملائیں۔ تقریباً 1/4 مکسچر چمچ سے ہر فلیٹ کے اوپر رکھیں۔ ہر فلیٹ کے گرد 10 ہری پھلیاں رکھیں۔","پارچمنٹ پیپر بند کرنے کے لیے دل کی شکل کے دوسرے حصے کو اجزا کو ڈھانپنے کے لیے موڑیں اور بند کرنے کے لیے کناروں کو ایک ساتھ دبا کر موڑیں۔ یقینی بنائیں کہ تھیلی کے اندر حرارت سے پھیلاؤ کے لیے کچھ جگہ رہے، جو مچھلی کے بیک ہونے کے دوران ہوگا۔ یقینی بنائیں کہ یہ ہوا بند ہو۔","12 منٹ بیک کریں یا جب تک مچھلی کانٹے سے آسانی سے پرت پرت نہ ہو جائے۔ پکانے کے بعد کاغذ کے اوپری حصے میں U کی شکل کاٹیں اور پیش کرنے کے لیے کھول دیں۔"],
["اگر پارچمنٹ پیپر دستیاب نہ ہو تو فوائل استعمال کریں۔","اگر 2” کے ٹکڑوں میں کاٹی جائیں تو چالیس تازہ ہری پھلیاں 2 کپ کے برابر ہوتی ہیں۔","پارباؤل کا مطلب ہے مختصر وقت کے لیے ابال کر جزوی طور پر پکانا۔","ہری پھلیوں کی جگہ کوئی بھی سبزی استعمال کی جا سکتی ہے، جیسے: لمبی پٹیوں میں کٹی پیلی اسکواش، زوکینی، گاجر، سنو پیز، وغیرہ۔ ہری پھلیوں اور سنو پیز جیسی موٹی، سخت سبزیوں کو مچھلی کے ساتھ بھاپ میں پکانے سے پہلے ہلکا ابالنا ضروری ہے تاکہ وہ پک جائیں۔ اسکواش سمیت نرم سبزیاں بغیر ہلکا ابالے استعمال کی جا سکتی ہیں۔","سول کو فلاؤنڈر بھی کہا جاتا ہے۔ متبادل میں ہیلی بٹ اور کاڈ شامل ہیں؛ دونوں اتنی ہی مزیدار ہیں۔","اگر دستیاب ہو تو خشک تلسی کی جگہ 1/2 کھانے کا چمچ تازہ تلسی استعمال کریں۔ بہترین ذائقے کے لیے اسے مچھلی بیک کرنے سے پہلے کے بجائے پارچمنٹ کھولنے کے فوراً بعد ڈالیں۔"],
["3 گوشت","1-1/2 سبزی، درمیانے پوٹاشیم والی"]))
dump(7,r)
